import string

ALPHA_UPPER = string.ascii_uppercase
ALPHA_LOWER = string.ascii_lower
ALPHABET_SIZE = 26
DEFAULT_PLACEHOLDER = '\n'


class EncryptionUtils:
    def __init__(self, key):
        self._key = key

    @property
    def key(self):
        return self._key

    @key.setter
    def key(self, value):
        if not isinstance(value, str):
            raise TypeError("Key must be a string")
        self._key = value

    def caesar_cipher(self, plaintext, shift):
        return ''.join(self._encrypt_char_caesar(char, shift) for char in plaintext)

    def _encrypt_char_caesar(self, char, shift):
        if not char.isalpha():
            return char
        is_upper = char.isupper()
        base_char = 'A' if is_upper else 'a'
        offset = ord(base_char)
        shifted_char = chr((ord(char) - offset + shift) % ALPHABET_SIZE + offset)
        return shifted_char

    def vigenere_cipher(self, plain_text):
        key_length = len(self.key)
        key_index = 0
        encrypted_chars = []
        for char in plain_text:
            if char.isalpha():
                key_char = self.key[key_index % key_length].lower()
                shift = ord(key_char) - ord('a')
                base_offset = ord('a')
                encrypted_char = chr((ord(char.lower()) - base_offset + shift) % ALPHABET_SIZE + base_offset)
                encrypted_chars.append(encrypted_char.upper() if char.isupper() else encrypted_char)
                key_index += 1
            else:
                encrypted_chars.append(char)
        return ''.join(encrypted_chars)

    def rail_fence_cipher(self, plain_text, rails):
        if rails <= 1:
            return plain_text
        fence = [[DEFAULT_PLACEHOLDER for _ in range(len(plain_text))] for _ in range(rails)]
        self._populate_fence(plain_text, fence, rails)
        return self._read_fence(fence)

    def _populate_fence(self, plain_text, fence, rails):
        direction = -1
        row, col = 0, 0
        for char in plain_text:
            if row == 0 or row == rails - 1:
                direction = -direction
            fence[row][col] = char
            col += 1
            row += direction

    def _read_fence(self, fence):
        encrypted_chars = []
        for i in range(len(fence)):
            for j in range(len(fence[i])):
                if fence[i][j] != DEFAULT_PLACEHOLDER:
                    encrypted_chars.append(fence[i][j])
        return ''.join(encrypted_chars)
